import { canonicalizeBundleFiles, normalizeBundlePath, skillJsonSchema, type CanonicalBundle } from "@skillplane/storage";
import { DomainError } from "./errors.js";
export interface GitSourceConfig { repositoryUrl:string; ref:string; refPolicy:"track"|"pin"; path:string|null }
export interface GitDiscoveredSkill { path:string; bundle:CanonicalBundle|null; error:string|null }
export interface GitSnapshot { commitSha:string; skills:GitDiscoveredSkill[] }
export interface GitSourceProvider { snapshot(config:GitSourceConfig, commitSha?:string):Promise<GitSnapshot> }
function invalid(message:string):never { throw new DomainError("VALIDATION_FAILED",message,400); }
export function gitSourceConfig(input:Record<string,unknown>):GitSourceConfig {
  if(typeof input.repositoryUrl!=="string") invalid("A public GitHub repository URL is required");
  let url:URL;try {url=new URL(input.repositoryUrl);} catch {invalid("Invalid repository URL");}
  const match=/^\/([A-Za-z0-9][A-Za-z0-9-]{0,38})\/([A-Za-z0-9_.-]{1,100}?)(?:\.git)?\/?$/.exec(url.pathname);
  if(url.protocol!=="https:" || url.hostname!=="github.com" || url.port || url.username || url.password || url.search || url.hash || !match || match[2]==="." || match[2]==="..") invalid("Use an HTTPS github.com owner/repository URL");
  const ref=input.ref??"HEAD", refPolicy=input.refPolicy??"track", path=input.path??null;
  if(typeof ref!=="string" || !ref || ref.length>200 || /[\x00-\x20\\?#]/u.test(ref)) invalid("A valid branch, tag, or commit is required");
  if(refPolicy!=="pin" && refPolicy!=="track") invalid("Ref policy must be track or pin");
  if(refPolicy==="pin" && !/^[a-f0-9]{40}$/i.test(ref)) invalid("Pinned sources require a full commit SHA");
  if(path!==null && (typeof path!=="string" || !safePath(path))) invalid("Skill path must be a safe repository-relative directory, or empty for repository-wide import");
  return {repositoryUrl:`https://github.com/${match[1]}/${match[2]}`,ref,refPolicy,path:path===""?"":path};
