function safePath(path:string) {return path==="" || (path.length<=240 && !/[\\\x00-\x1f]/u.test(path) && !path.startsWith("/") && !/^[A-Za-z]:/.test(path) && path.split("/").every(s=>s && s!=="." && s!==".." && s!=="~"));}
