interface TreeEntry {path:string;mode:string;type:string;sha:string;size:number}
const MAX_SNAPSHOT_BYTES=20*1024*1024, MAX_BLOB_BYTES=5*1024*1024, MAX_REQUESTS=200;
export class PublicGitHubSourceProvider implements GitSourceProvider {
  constructor(private readonly fetcher:typeof fetch=globalThis.fetch) {}
  async snapshot(input:GitSourceConfig,pinned?:string):Promise<GitSnapshot> {
    const config=gitSourceConfig({...input});
    if(pinned && !/^[a-f0-9]{40}$/i.test(pinned)) invalid("Invalid preview commit");
    const repository=config.repositoryUrl.slice("https://github.com/".length);
    let requests=0, totalBytes=0;
    const read=async(path:string,maxBytes:number)=>{
      if(++requests>MAX_REQUESTS) invalid("Repository exceeds the 200 request import limit; select one skill path");
      let response:Response;
      try {response=await this.fetcher(`https://api.github.com/repos/${repository}/${path}`,{headers:{accept:"application/vnd.github+json","x-github-api-version":"2026-03-10","user-agent":"Skillplane-public-source-import"},redirect:"error",signal:AbortSignal.timeout(10000)});} catch {throw new DomainError("SERVICE_UNAVAILABLE","GitHub could not be reached; retry later",503);}
